// Notices ("avisos"): generated by the system or written by a person, each with its recipients.
const { Op } = require('sequelize');
const { Notice, NoticeRecipient, User } = require('../models');
const { NOTICE_KIND, LESSON_STATUS } = require('../domain/constants');
const { formatInstant, formatDay } = require('../domain/time');
const { formatCOP } = require('../domain/money');
const { pendingMakeupDeadline } = require('../domain/classRules');

const createNotice = async ({ kind = NOTICE_KIND.SISTEMA, category, title, message, recipientIds, authorId = null, meta = null }, { transaction } = {}) => {
    const ids = [...new Set((recipientIds || []).filter(Boolean))];
    if (!ids.length) return null;
    const notice = await Notice.create({ kind, category, title, message, authorId, meta }, { transaction });
    await NoticeRecipient.bulkCreate(ids.map(userId => ({ noticeId: notice.id, userId })), { transaction });
    return notice;
};

const listNoticesFor = async (userId, { limit = 30 } = {}) => {
    const rows = await NoticeRecipient.findAll({
        where: { userId },
        include: [{ model: Notice, as: 'notice' }],
        order: [['createdAt', 'DESC']],
        limit,
    });
    return rows.map(r => ({ ...r.notice.get({ plain: true }), recipientId: r.id, readAt: r.readAt }));
};

/**
 * Notices still worth showing: every unread one plus the read ones from the
 * last keepReadDays days. Older read notices only appear in the history.
 */
const listRecentNoticesFor = async (userId, { keepReadDays, now = new Date(), limit = 50 }) => {
    const cutoff = new Date(new Date(now).getTime() - keepReadDays * 24 * 60 * 60 * 1000);
    const rows = await NoticeRecipient.findAll({
        where: { userId, [Op.or]: [{ readAt: null }, { createdAt: { [Op.gte]: cutoff } }] },
        include: [{ model: Notice, as: 'notice' }],
        order: [['createdAt', 'DESC']],
        limit,
    });
    return rows.map(r => ({ ...r.notice.get({ plain: true }), recipientId: r.id, readAt: r.readAt }));
};

const markRead = (userId, noticeIds) =>
    NoticeRecipient.update(
        { readAt: new Date() },
        { where: { userId, readAt: null, ...(noticeIds ? { noticeId: { [Op.in]: noticeIds } } : {}) } }
    );

// --- Notices sent when lessons change ---

/** The teacher or academy cancelled lessons: each student is told the teacher will book the make-up, and by when. */
const notifyCancellations = async (lessons, actor) => {
    for (const lesson of lessons) {
        const who = lesson.status === LESSON_STATUS.CANCELADA_POR_ACADEMIA ? 'La academia' : 'Tu profesor';
        const reason = lesson.reason ? ` Motivo: ${lesson.reason}.` : '';
        await createNotice({
            category: 'clase_cancelada',
            title: 'Clase cancelada',
            message: `${who} canceló tu clase del ${formatInstant(lesson.startsAt)}. No la pierdes: tu profesor te asignará la reposición a más tardar el ${formatDay(pendingMakeupDeadline(lesson))}.${reason}`,
            recipientIds: [lesson.studentId],
            authorId: actor.id,
            meta: { lessonId: lesson.id },
        });
    }
};

/** A lesson was moved or a make-up booked: tell whoever did not do it. */
const notifyMakeupBooked = async ({ original, makeup, actor, rescheduled }) => {
    const student = await User.findByPk(makeup.studentId, { attributes: ['id', 'name'] });
    const when = formatInstant(makeup.startsAt);
    if (actor.id === makeup.studentId) {
        await createNotice({
            category: rescheduled ? 'clase_reprogramada' : 'reposicion_agendada',
            title: rescheduled ? 'Clase cambiada' : 'Reposición agendada',
            message: rescheduled
                ? `${student.name} cambió su clase del ${formatInstant(original.startsAt)} para el ${when}.`
                : `${student.name} agendó la reposición de la clase del ${formatInstant(original.startsAt)} para el ${when}.`,
            recipientIds: [makeup.teacherId],
            authorId: actor.id,
            meta: { lessonId: makeup.id },
        });
    } else {
        await createNotice({
            category: 'reposicion_agendada',
            title: 'Reposición agendada',
            message: `Tu reposición de la clase del ${formatInstant(original.startsAt)} quedó para el ${when}.`,
            recipientIds: [makeup.studentId],
            authorId: actor.id,
            meta: { lessonId: makeup.id },
        });
    }
};

/**
 * Payment confirmed. The student learns their first class or that the teacher
 * will schedule it; the teacher is asked to schedule a cycle that has no lessons yet.
 */
const notifyPaymentConfirmed = async ({ cycle, lessons, unscheduled, actor }) => {
    const student = await User.findByPk(cycle.studentId, { attributes: ['id', 'name', 'teacherId'] });
    const first = lessons.find(l => l.status === LESSON_STATUS.PROGRAMADA);
    await createNotice({
        category: 'pago_confirmado',
        title: 'Pago confirmado',
        message: unscheduled
            ? `La academia confirmó tu pago de ${formatCOP(cycle.amount)}. Tu profesor agendará tus clases y te avisaremos.`
            : `La academia confirmó tu pago de ${formatCOP(cycle.amount)}. Tu ciclo va del ${formatDay(cycle.startDate)} al ${formatDay(cycle.endDate)}`
                + (first ? ` y tu primera clase es el ${formatInstant(first.startsAt)}.` : '.'),
        recipientIds: [cycle.studentId],
        authorId: actor.id,
        meta: { cycleId: cycle.id },
    });
    if (unscheduled && student?.teacherId) {
        await createNotice({
            category: 'clases_por_agendar',
            title: 'Clases por agendar',
            message: `${student.name} ya pagó su mensualidad. Agéndale su horario en Mi agenda.`,
            recipientIds: [student.teacherId],
            authorId: actor.id,
            meta: { cycleId: cycle.id },
        });
    }
};

/** A lesson the teacher moved to another time. */
const notifyLessonMoved = async ({ original, makeup, actor }) => {
    await createNotice({
        category: 'clase_movida',
        title: 'Clase movida',
        message: `Tu clase del ${formatInstant(original.startsAt)} se movió para el ${formatInstant(makeup.startsAt)}.`,
        recipientIds: [makeup.studentId],
        authorId: actor.id,
        meta: { lessonId: makeup.id },
    });
};

module.exports = {
    createNotice, listNoticesFor, listRecentNoticesFor, markRead, notifyCancellations, notifyMakeupBooked, notifyPaymentConfirmed, notifyLessonMoved,
};
